INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idk-mis250', 'stk-idk', 'MIS 250', 'doc', '{"docs": [{"id": "stk-dr-f98426", "n": "Dr. Mustafa Ahmed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "المقرر والترم الدراسي: MIS250-242\n\nالتحضير:\n\nنهاية الكلاس عن طريق الباركود\n\nالشرح والتعامل :\n\nتعامله كويس واخلاقه كويسة دايم الابتسامة على وجهه بالنسبة للشرح الرجال راعي سواليف مو حق شرح يعني المادة بتقلب لك سلف ستدي لكن سوالفه مفيدة ويعطيك اخبار عن الي صاير في مجال التقنية والخ ويتكلم عن ريادة الاعمال والخ يعني بختصار بيسولف عليك وانسى شرحه لكن كويس عموما + لكن اذا عندك سؤال عن موضوع بالدرس بيقدر يشرحه لك بشكل كويس\n\nأعمال السنة :\n\nاللاب كومن بالنسبة للكلاس وورك ينزل مرات كلاس اكتيفيتي ويبغاك تحلها قبل ما يخلص الكلاس وغالبا تكون عبارة عن بحث قصير تسويه وترسله الاجابة يعني الحلو في ذا الدكتور انه ماراح يتعبك مرا\n\nالاختبارات :\n\nبالنسبة للكويزات سهلة والميد كان سهل والفاينل كان اصعب بخفيف من الميد لكن مشكلة هذا الكورس الكتاب فيه حشو مو طبيعي يعني يبالك تصبر صبر مو طبيعي على مذاكرة الكورس لان فيه اشياء كثيرة مو واضحة لكن عموما بما انه هو كان الكورد على ترمي فكانت الامور طيبة واغلب الشباب كانو راضين عن درجاتهم\n\nإضافات:\n\nدكتور حبيب وبتشوفه بمواد كثير اذا تخصصك mis لكن حاول لا تصير بجيح معه من ناحية الحضور او انك تقعد على الجوال واجد جاول تشارك معه وبتكون اوضاعك مزبوطة واخيرا خلك صبور معه الدكتور عنده اشغال واجد يعني احنا اختبرنا الميد اول يوم رمضان وما شفنا درجاتنا الا بعد اجازة العيد عكس باقي السكاشن شافو درجاتهم في نفس الاسبوع لكن بالنهاية قبل رفع الدرجات وبعد الفاينلات بيرفع لك كل شي وبتكون راضي باذن الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1539745-mis250", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mustafa-ahmed/98426/15", "user": "idk", "ts": 1749142017806, "tid": 98426, "pn": 15}}]}', 1749142017806, 1794774615, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
